        out=[]; start=0
        for x in cuts:
            if start < x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    rb=intervals(h,sep_rows); cb=intervals(w,sep_cols)
    # The key panel in the first column identifies each row band's color.
    # Find the non-key panel holding the stencil and retain its offsets.
    key_colors=[]
    for r0,r1 in rb:
        vals=[grid[r][c] for r in range(r0,r1) for c in range(cb[0][0],cb[0][1]) if grid[r][c] not in (0,sep)]
        key_colors.append(vals[0] if vals else None)
    template_band=next((i for i,color in enumerate(key_colors) if color is not None and any(grid[r][c] not in (0,sep) for r in range(rb[i][0],rb[i][1]) for c in range(cb[1][0],cb[1][1]))),None)
    if template_band is None: return [row[:] for row in grid]
    r0,r1=rb[template_band]; c0,c1=cb[1]
    stencil={(r-r0,c-c0) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] not in (0,sep)}
